"""Build a local, evidence-linked report from actual map10 measurements."""
import json
from pathlib import Path
import statistics
from html import escape

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT/'optimization_reports/live_map10'
results = json.loads((OUT/'results.json').read_text(encoding='utf-8'))
labels = {'baseline':'修改前', 'quality':'quality · 默认', 'balanced':'balanced', 'performance':'performance'}
summary = {}
for name in labels:
    runs = [r for r in results['runs'] if r['profile']==name]
    work = []
    for r in runs:
        raw = json.loads((OUT/f"{name}_{r['repeat']}_samples.json").read_text(encoding='utf-8'))
        work.extend(raw['work_ms'])
    ordered = sorted(work)
    summary[name] = {'front_fps':statistics.mean(r['cameras']['front']['displayed_unique_fps'] for r in runs),
        'front_range':[min(r['cameras']['front']['displayed_unique_fps'] for r in runs),max(r['cameras']['front']['displayed_unique_fps'] for r in runs)],
        'server_fps':statistics.mean(r['server_fps'] for r in runs),
        'display_fps':statistics.mean(r['display_fps'] for r in runs),
        'received_fps':statistics.mean(r['cameras']['front']['received_fps'] for r in runs),
        'work_p50':statistics.median(work),'work_p95':ordered[round((len(ordered)-1)*.95)],
        'gpu':statistics.mean(r['gpu_util_percent']['mean'] for r in runs),
        'memory':statistics.mean(r['gpu_memory_mib']['mean'] for r in runs),
        'left_fps':statistics.mean(r['cameras']['left']['displayed_unique_fps'] for r in runs)}
baseline, quality = summary['baseline'], summary['quality']
gain = (quality['front_fps']/baseline['front_fps']-1)*100
reduction = (1-quality['work_p50']/baseline['work_p50'])*100
(OUT/'summary.json').write_text(json.dumps(summary,indent=2),encoding='utf-8')

rows = ''.join(f'<tr><th>{labels[name]}</th><td><b>{r["front_fps"]:.1f}</b><small>{r["front_range"][0]:.1f}–{r["front_range"][1]:.1f}</small></td><td>{r["received_fps"]:.1f}</td><td>{r["display_fps"]:.1f}</td><td>{r["server_fps"]:.1f}</td><td>{r["work_p50"]:.1f} / {r["work_p95"]:.1f}</td><td>{r["gpu"]:.0f}%</td></tr>' for name,r in summary.items())
bars = ''.join(f'<div class="barline"><span>{labels[name]}</span><div class="track"><div class="bar {name}" style="width:{r["front_fps"]/60*100:.1f}%"></div></div><b>{r["front_fps"]:.1f}</b></div>' for name,r in summary.items())
validations = []
for path in sorted(OUT.glob('*_validation.json')):
    r = json.loads(path.read_text(encoding='utf-8'))
    evidence = r.get('analysis',{})
    ok = not r['timeout'] and not r['error'] and not r['remaining_dynamic_actors'] and not evidence.get('runtime_errors') and not r.get('thread_errors')
    validations.append(f'<tr><th>{escape(r["scene"])}</th><td>{"正常结束" if ok else "发现问题"}</td><td>{r["wall_duration_s"]:.1f} 秒</td><td>{escape(str(evidence.get("stages", "待分析")))}</td><td>{"有" if evidence.get("collision") else "无"}</td><td><a href="optimization_reports/live_map10/{path.name}">记录</a></td></tr>')

html = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>map10 修改前后 · 实机画面与速度</title><style>
:root{--ink:#182e37;--sub:#60737e;--green:#067f70;--line:#dce6e9}*{box-sizing:border-box}body{margin:0;background:#f2f6f7;color:var(--ink);font:16px/1.8 "Microsoft YaHei","Segoe UI",sans-serif}main{max-width:1320px;margin:auto;padding:40px 28px 70px}header{padding:22px 0}h1{font-size:clamp(30px,4vw,48px);line-height:1.3;margin:16px 0}h2{font-size:26px;line-height:1.4;margin:0 0 18px}h3{margin:0 0 8px}p{margin:10px 0}.eyebrow{color:var(--green);font-size:13px;font-weight:700;letter-spacing:2px}.lead{font-size:20px;color:var(--sub);max-width:960px}.pill{display:inline-block;background:#e0eee9;color:#236957;border-radius:24px;padding:3px 12px;margin:4px 5px 4px 0;font-size:13px}section{background:white;border:1px solid var(--line);border-radius:14px;padding:28px;margin:24px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:#f7faf9;border:1px solid var(--line);border-radius:10px;padding:22px}.metric{font-size:39px;line-height:1.4;color:var(--green);font-weight:750}.muted,small{color:var(--sub);font-size:13px}small{display:block}.notice{padding:16px 20px;border-left:4px solid #c89b36;background:#fff7e8;border-radius:5px;margin:18px 0;font-size:14px}.good{border-color:var(--green);background:#eaf6f2}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:18px 0}button,select{font:inherit;padding:8px 14px;background:white;color:var(--ink);border:1px solid #b8cccf;border-radius:6px;cursor:pointer}button:hover{background:#eaf6f2}input[type=range]{width:min(420px,65vw);accent-color:var(--green)}a{color:var(--green);text-underline-offset:4px}.panorama{position:relative;aspect-ratio:5740/1010;background:#182e37;overflow:hidden;border-radius:8px}.panorama img{position:absolute;inset:0;width:100%;height:100%}.panorama .after{clip-path:inset(0 50% 0 0)}.divider{position:absolute;left:50%;top:0;bottom:0;border-left:3px solid white;pointer-events:none}.badges{display:flex;justify-content:space-between;font-size:13px;margin:8px 0}.zoom{display:grid;grid-template-columns:1fr 1fr;gap:16px}.zoom canvas{width:100%;height:auto;border:1px solid var(--line);border-radius:6px;background:#edf3f4}.videos{display:grid;grid-template-columns:1fr;gap:18px}video{width:100%;background:#101d24;border-radius:7px}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:13px;text-align:left;border-bottom:1px solid var(--line)}thead{background:#edf3f5}td{white-space:nowrap}.barline{display:grid;grid-template-columns:160px 1fr 50px;gap:14px;align-items:center;margin:14px 0;font-size:14px}.track{height:28px;border-radius:5px;background:#edf2f4;overflow:hidden}.bar{height:100%;background:#8a9da7}.bar.quality{background:#087f70}.bar.balanced{background:#58a599}.bar.performance{background:#a7c8be}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:24px}details{padding:18px;border:1px solid var(--line);border-radius:8px;margin:18px 0}summary{cursor:pointer;font-weight:650}li{margin:8px 0}code{background:#edf3f4;border-radius:4px;padding:2px 5px;overflow-wrap:anywhere}pre{white-space:pre-wrap;background:#17313c;color:#e3f4ef;padding:18px;border-radius:7px;font:13px/1.9 Consolas,monospace}footer{color:var(--sub);font-size:13px}@media(max-width:780px){main{padding:20px 14px}.cards,.zoom,.twocol{grid-template-columns:1fr}section{padding:20px 16px}.barline{grid-template-columns:100px 1fr 40px;gap:8px}.metric{font-size:32px}h2{font-size:23px}}@media print{button,select,input,video{display:none}body{background:white}main{padding:0}section{break-inside:avoid}a{color:inherit}}
</style></head><body><main><header><div class="eyebrow">MAP10 / 2026.10.02 / 实机对照</div><h1>画面保留多少，<br>实际快了多少。</h1><p class="lead">已在你启动的自定义 map10 上完成原版与三个档位的两轮测试。默认 quality 档保持前视原尺寸，实际新画面从 <b>@BASE FPS 提升到 @QUALITY FPS</b>。</p><span class="pill">RTX 4080 SUPER</span><span class="pill">CARLA 0.9.15 / 0.9.15-dirty</span><span class="pill">四路真实 RGB 相机</span><span class="pill">每档 2 × 30 秒</span><p class="muted"><a href="optimization_report.html">返回完整项目优化报告</a> · <a href="#visual">看画面</a> · <a href="#motion">看行驶视频</a> · <a href="#speed">看速度数据</a></p></header>
<div class="cards"><div class="card"><small>默认档 · 前视新画面提升</small><div class="metric">+@GAIN%</div><p>@BASE → @QUALITY FPS</p><small>统计实际显示的新 Surface，重复刷新不计入</small></div><div class="card"><small>服务器更新速度 · 两轮平均</small><div class="metric">@SERVER_OLD → @SERVER_NEW</div><p>tick / 秒</p><small>世界更新频率；RGB 新画面速度见左侧指标</small></div><div class="card"><small>默认档 · 前视采样尺寸</small><div class="metric" style="font-size:30px">5740 × 1010</div><p>与修改前一致</p><small>镜面采样上限 30 Hz；左右镜面改为水平翻转</small></div></div>
<section id="visual"><div class="eyebrow">01 / 真实输出截图</div><h2>拖动分界线，看同一位置的差异。</h2><p>车辆位置、颜色、天气、镜头位置和 FOV 固定。这里显示的是实际程序输出，包含原驾驶舱叠图。原尺寸 PNG 可以单独打开查看。</p><div class="toolbar"><label for="profile">修改后档位</label><select id="profile"><option value="quality">quality · 默认 / 原分辨率</option><option value="balanced">balanced · 前视 75%</option><option value="performance">performance · 前视 50%</option></select><label for="split">分界线</label><input type="range" id="split" min="0" max="100" value="50" aria-label="修改前后分界线"></div><div class="badges"><b id="after-label">左侧：quality 修改后</b><span>右侧：原版</span></div><div class="panorama"><img id="before" src="optimization_reports/live_map10/baseline_composite.png" alt="原版完整驾驶画面"><img id="after" class="after" src="optimization_reports/live_map10/quality_composite.png" alt="优化后完整驾驶画面"><div id="divider" class="divider"></div></div><p class="muted"><a id="original-link" href="optimization_reports/live_map10/baseline_composite.png" target="_blank">原版完整原图</a> · <a id="updated-link" href="optimization_reports/live_map10/quality_composite.png" target="_blank">当前优化档完整原图</a> · <a id="native-link" href="optimization_reports/live_map10/quality_front_native.png" target="_blank">当前档相机原生分辨率图</a></p><div class="toolbar"><label for="detail">放大细节</label><select id="detail"><option value="front">前方车辆与标线</option><option value="left">左后视镜</option><option value="right">右后视镜</option></select></div><div class="zoom"><div><b>修改前</b><canvas id="crop-before" width="1000" height="500"></canvas></div><div><b id="crop-label">quality 修改后</b><canvas id="crop-after" width="1000" height="500"></canvas></div></div><div class="notice good"><b>可直接看到的变化：</b>quality 的前视整体外观与原版接近，主要可见变化是左右后视镜的镜像方向。建筑、材质、光照与天气沿用当前地图；这次没有重做场景资产。balanced 和 performance 会损失前方小目标与边缘细节。</div><p class="muted">放大区由原图裁切显示。不同异步渲染时刻的抗锯齿、云层细节可能略有差异，不能把这些像素差异全部归因于优化。相机配置中关闭了运动模糊；本地图静止截图不用于判断运动模糊改善程度。</p></section>
<section id="motion"><div class="eyebrow">02 / 行驶中的视觉表现</div><h2>同一路线，12 秒前后对照。</h2><p>两段使用同一条直线轨迹、相同车距和 50 km/h 位移速度。上面的档位选择也会切换下方视频。点击同步播放，从同一位置开始比较。</p><div class="toolbar"><button id="play-both">从头同步播放</button><button id="pause-both">一起暂停</button></div><div class="videos"><div><b>修改前</b><video id="video-before" controls muted playsinline preload="metadata" src="optimization_reports/live_map10/baseline_motion.mp4"></video></div><div><b id="video-label">quality 修改后</b><video id="video-after" controls muted playsinline preload="metadata" src="optimization_reports/live_map10/quality_motion.mp4"></video></div></div><p class="muted">这些视频是相机画质演示：关闭车辆物理、按同一轨迹移动，便于对齐视点，不是控车真实性或风险时序验收。视频统一为 1920×338、24 FPS；录制与编码开销未混入下方速度测试，也不能从视频容器的 24 FPS 推算程序帧率。</p></section>
<section id="speed"><div class="eyebrow">03 / 实际渲染与显示速度</div><h2>默认档最快提供新的前视画面。</h2><p>条形图：前视<b>实际显示的新画面 / 秒</b>，越高越好。两轮平均；原始每轮结果及采样数据均可追溯。</p>@BARS<div class="table-wrap"><table><thead><tr><th>配置</th><th>前视新画面 FPS<br><small>均值 / 两轮范围</small></th><th>前视接收 FPS</th><th>窗口刷新 FPS</th><th>服务器 tick/s</th><th>显示耗时 ms<br><small>P50 / P95</small></th><th>全机 GPU</th></tr></thead><tbody>@ROWS</tbody></table></div><p class="muted">显示耗时不能直接比较为总处理成本：原版在相机回调线程转换图像，新版把这项工作移到了显示线程。判断实际流畅度，请看“前视新画面 FPS”。</p><div class="notice"><b>为何 balanced 不比 quality 快：</b>这一实现先降低相机尺寸，再通过 CPU 平滑缩放回 5740×1010。实测显示处理时间增加，抵消了减少相机像素的收益。performance 的前视主动限制为 30 Hz，即使服务器 tick 更快，也不可能持续提供 60 张新前视画面。</div><p><b>这台机器当前优先用 quality。</b>它保留前视尺寸，在本次场景中提供最多的新画面。不同地图、更多背景车或不同显示设备可能改变瓶颈，应再测对应工作负载。</p><details><summary>测试条件与指标定义</summary><ul><li>自定义地图 <code>package/Maps/map10/map10</code>，UE 编辑器 Play 会话、异步模式、未切换世界设置或天气。RTX 4080 SUPER，驱动 610.60。没有打开 no_rendering_mode。</li><li>同一组 5 辆静止车辆：Tesla、两辆 Audi TT、消防车与 Ninja 摩托车。四相机位置及 5740×1010 显示布局与 Scene1_01 一致。</li><li>顺序：原版 → quality → balanced → performance → performance → balanced → quality → 原版。每次预热 8 秒、计时 30 秒，每档合计 60 秒。PNG 保存与视频录制在计时范围外。</li><li>原版来自 <code>optimization_backup/20261001/Set_sensor.py</code>。本机 Pygame 遍历字体注册表报 TypeError，因此仅为原版加同样的 Arial 文件回退，两组均只检测一次字体注册表故障，原版仍保留每次刷新创建字体的逻辑；备份文件未改。首轮额外字体枚举开销已排除，表中使用修正后的复测数据。优化版仍缓存字体与车速文本。</li><li>新画面 FPS：本显示循环实际 blit 的不同 Surface 数量 / 墙钟秒；窗口刷新 FPS 包含重复显示。前视接收 FPS 是相机回调到达频率。服务器 tick/s 是世界更新频率，不等于 RGB 新画面速度。</li><li>显示耗时包含该次 render 与 flip；原版的 BGRA 转换在回调线程，新版把转换移到显示线程，因此不能直接把两列相减当作转换优化收益；这个耗时也不是全部 CPU 或 GPU 帧时间。P50/P95 合并两轮显示样本计算。</li><li>GPU 利用率来自 nvidia-smi，每秒采样，包含 UE 编辑器和其他应用。不是独占相机利用率。未测显示器物理呈现或端到端输入延迟。</li><li>两轮是短时重复验证，不是长期稳定性统计；静态场景结果不代表所有风险场景或高车流负载。</li></ul></details></section>
<section id="scenes"><div class="eyebrow">04 / 实际控车试跑</div><h2>实验场景的运行记录。</h2><div class="notice"><b>试跑中发现并修复：</b>① Windows 字体注册表异常导致显示初始化失败；② 接管监听在 Pygame 退出后继续读键盘；③ 消防车的 5000 rpm 上限使升挡门槛超过其约 2571 rpm 的扭矩曲线末端。已按该车实际扭矩曲线修正转速上限，质量、扭矩与齿比不变；同时恢复原实验的行驶初始速度，只在启动时赋值一次，之后使用物理油门/刹车。<br>Scene1_01 复测：消防车在阶段 2 达到约 50.9 km/h，阶段 3 与主车纵向距离约 3.1 m；修正前约为 165 m。仍需逐事件校验摩托车位置与风险显现时序，不能宣称轨迹与原版完全相同。</div><p>使用 quality、background=0、当前天气进行无人接管试跑。危险场景发生碰撞并不自动表示脚本异常；完整退出也不代表遮挡和接管时序已经满足正式实验要求。Scene2 无人接管试跑记录到碰撞；该场景未被判定为正式接管验收通过。</p><div class="table-wrap"><table><thead><tr><th>场景</th><th>执行</th><th>墙钟耗时</th><th>阶段值</th><th>碰撞记录</th><th>证据</th></tr></thead><tbody>@VALIDATIONS</tbody></table></div><p class="muted">需要人工接管的场景，在无人操作时可能继续碰撞或偏离预期轨迹。正式被试实验仍应按风险暴露时刻、TTC、遮挡关系和手动接管校验。</p></section>
<section><div class="eyebrow">05 / 文件与复测</div><h2>数据、画面和脚本都在项目内。</h2><p><a href="optimization_reports/live_map10/results.json">逐轮性能与条件</a> · <a href="optimization_reports/live_map10/summary.json">汇总数据</a> · <a href="optimization_reports/live_map10/motion_results.json">视频条件与清理记录</a> · <a href="tools/live_render_benchmark.py">性能测试脚本</a> · <a href="tools/live_motion_comparison.py">视频采集脚本</a></p><pre>Set-Location 'E:\Scene_package\Scene_HYX'
python tools/live_render_benchmark.py --seconds 30 --warmup 8 --repeats 2
python tools/live_motion_comparison.py
python tools/build_live_report.py

# 日常试跑：默认档
python run_scene.py Scene1_01 --profile quality</pre><p>实机中修复的字体兼容问题（故障只检测一次）：<code>display_font.py</code>，由 <code>Set_sensor.py</code> 使用。测试只销毁自己生成的车辆和相机，结束后保留已启动的 map10 会话。</p></section><footer>2026-10-02 · 本地实测，无合成场景画面。完整数据目录：optimization_reports/live_map10/。</footer></main><script>
const prefix='optimization_reports/live_map10/';const profile=document.getElementById('profile');const before=document.getElementById('before'),after=document.getElementById('after');
function crop(){const boxes={front:[2400,280,1000,500],left:[700,580,670,420],right:[4719,570,655,415]};const box=boxes[document.getElementById('detail').value];for(const [img,id] of [[before,'crop-before'],[after,'crop-after']]){const c=document.getElementById(id);c.height=Math.round(1000*box[3]/box[2]);if(img.complete&&img.naturalWidth)c.getContext('2d').drawImage(img,...box,0,0,c.width,c.height)}}
before.addEventListener('load',crop);after.addEventListener('load',crop);document.getElementById('detail').addEventListener('change',crop);crop();
document.getElementById('split').addEventListener('input',e=>{after.style.clipPath=`inset(0 ${100-e.target.value}% 0 0)`;document.getElementById('divider').style.left=e.target.value+'%'});
const vb=document.getElementById('video-before'),va=document.getElementById('video-after');profile.addEventListener('change',()=>{const p=profile.value;after.src=prefix+p+'_composite.png';document.getElementById('after-label').textContent='左侧：'+p+' 修改后';document.getElementById('crop-label').textContent=p+' 修改后';document.getElementById('video-label').textContent=p+' 修改后';document.getElementById('updated-link').href=after.src;document.getElementById('native-link').href=prefix+p+'_front_native.png';vb.pause();va.pause();va.src=prefix+p+'_motion.mp4'});
document.getElementById('play-both').addEventListener('click',async()=>{vb.currentTime=0;va.currentTime=0;await Promise.allSettled([vb.play(),va.play()])});document.getElementById('pause-both').addEventListener('click',()=>{vb.pause();va.pause()});vb.addEventListener('timeupdate',()=>{if(!vb.paused&&!va.paused&&Math.abs(vb.currentTime-va.currentTime)>.2)va.currentTime=vb.currentTime});
</script></body></html>'''
replacements = {'@BASE':f'{baseline["front_fps"]:.1f}', '@QUALITY':f'{quality["front_fps"]:.1f}', '@GAIN':f'{gain:.1f}',
    '@OLD':f'{baseline["work_p50"]:.1f}','@NEW':f'{quality["work_p50"]:.1f}','@REDUCTION':f'{reduction:.1f}',
    '@SERVER_OLD':f'{baseline["server_fps"]:.1f}','@SERVER_NEW':f'{quality["server_fps"]:.1f}', '@BARS':bars,'@ROWS':rows,'@VALIDATIONS':''.join(validations) or '<tr><td colspan="6">试跑结果正在采集。</td></tr>'}
for key,value in replacements.items():
    html = html.replace(key,value)
(ROOT/'map10_comparison.html').write_text(html,encoding='utf-8')
print(ROOT/'map10_comparison.html')
